#!/usr/bin/env python3
# Original reimplementation of the SoX command-line audio tool (behavioural clone).
import sys, os, math, struct, re, random, glob as globmod, subprocess, shlex, time
from array import array

try:
    from texts import HELP_MAIN, HELP_EFFECTS_ALL_BODY, HELP_FORMATS_ALL_BODY, HELP_SOXI
except Exception:
    HELP_MAIN=""; HELP_EFFECTS_ALL_BODY=""; HELP_FORMATS_ALL_BODY=""; HELP_SOXI=""

PROG = sys.argv[0] if sys.argv else "sox"
VERSION = "14.4.2"
VERBOSITY = 2
SHOW_PROGRESS = False
NO_DITHER = False
USE_RANDOM_SEED = False
RNG = random.Random()
