FORMAT_NAMES = ["8svx","aif","aifc","aiff","aiffc","al","amb","au","avr","cdda","cdr","cvs","cvsd","cvu","dat","dvms","f32","f4","f64","f8","fssd","gsrt","hcom","htk","ima","ircam","la","lpc","lpc10","lu","maud","nist","prc","raw","s1","s16","s2","s24","s3","s32","s4","s8","sb","sf","sl","sln","smp","snd","sndr","sndt","sou","sox","sph","sw","txw","u1","u16","u2","u24","u3","u32","u4","u8","ub","ul","uw","vms","voc","vox","wav","wavpcm","wve","xa"]

def prog_name():
    return PROG

def eprint(s=""):
    sys.stderr.write(str(s)+"\n")

def log_fail(mod, msg):
    if VERBOSITY >= 1:
        eprint(f"{PROG} FAIL {mod}: {msg}")
def log_warn(mod, msg):
    if VERBOSITY >= 2:
        eprint(f"{PROG} WARN {mod}: {msg}")
def log_info(mod, msg):
    if VERBOSITY >= 3:
        eprint(f"{PROG} INFO {mod}: {msg}")

class Fail(Exception):
    def __init__(self, msg, mod="sox", code=1):
        super().__init__(msg); self.msg=msg; self.mod=mod; self.code=code

def version_line():
    return f"{PROG}:      SoX v{VERSION}"

def print_help_main():
    sys.stdout.write(version_line()+"\n"+HELP_MAIN)

def print_soxi_help():
    sys.stdout.write(version_line()+"\n"+HELP_SOXI)

# ---------- parsing helpers ----------
def parse_float(s):
    try:
        return float(s)
    except Exception:
        return None

def parse_freq(s, allow_percent=True):
    """Return frequency in Hz or None. Handles k, %semitone, note names."""
    if s is None: return None
    orig=s; s=s.strip()
    if not s: return None
    if allow_percent and s.startswith('%'):
        v=parse_float(s[1:])
        if v is None: return None
        return 440.0 * (2.0 ** (v/12.0))
    # scientific note e.g. C#4, Eb3, A2
    m=re.match(r'^([A-Ga-g])([#b]?)(-?\d+)$', s)
    if m:
        note=m.group(1).upper(); acc=m.group(2); octv=int(m.group(3))
        base={'C':0,'D':2,'E':4,'F':5,'G':7,'A':9,'B':11}[note]
        if acc=='#': base+=1
        elif acc=='b': base-=1
        midi=(octv+1)*12+base
        return 440.0 * (2.0 ** ((midi-69)/12.0))
    mult=1.0
    if s[-1] in ('k','K'):
        mult=1000.0; s=s[:-1]
    v=parse_float(s)
    if v is None: return None
    return v*mult

def parse_rate(s):
    if s is None: return None
    s=str(s).strip()
    if s.lower().endswith('hz'):
        s=s[:-2]
    return parse_freq(s, allow_percent=False)

def parse_time_terms(s, rate):
    """Parse timespec to seconds (float). Supports colon times, sample suffix s, + / - chaining."""
    if s is None: return None
    s=str(s).strip()
    if not s: return None
    # Split into signed terms keeping +/-
    terms=[]; cur=''; i=0
    # handle leading sign externally in scanning
    parts=[]; start=0
    for i,ch in enumerate(s):
        if ch in '+-' and i!=0:
            parts.append(s[start:i]); start=i
    parts.append(s[start:])
    total=0.0
    for part in parts:
        sign=1.0
        if part.startswith('+'): part=part[1:]
        elif part.startswith('-'): sign=-1.0; part=part[1:]
        if part=='':
            val=0.0
        elif part.endswith('s') or part.endswith('S'):
            # sample count, may be e notation
            v=parse_float(part[:-1])
            if v is None: return None
            if not rate: return None
            val=v/float(rate)
        else:
            # colon time
            val=0.0
            comps=part.split(':')
            for c in comps:
                if c=='':
                    fv=0.0
                else:
                    fv=parse_float(c)
                    if fv is None: return None
                val=val*60.0+fv
        total+=sign*val
    return total

def time_to_samples(s, rate, total_frames=None, prev=None, default_prefix='='):
    """Parse a position spec. Returns sample frame index (float -> int rounded) or None"""
    if s is None: return None
    orig=str(s)
    prefix=default_prefix
    body=orig
    if body and body[0] in ('=','+','-'):
        # '-' could mean relative-to-end, '+' relative to prev; but a negative timespec without =/+ also?
        # SoX: leading '-' means from end, '+' means from previous, '=' absolute.
        prefix=body[0]; body=body[1:]
        if prefix=='-' and body=='':
            body='0'
    sec=parse_time_terms(body, rate)
    if sec is None:
        # body may be like "-0.5+1s"? That would have been prefix '-' then remaining "0.5+1s" ok.
        return None
    pos_sec=sec
    if prefix=='=':
        frames=pos_sec*rate
    elif prefix=='+':
        base=(prev if prev is not None else 0)
        frames=base+pos_sec*rate
    elif prefix=='-':
        if total_frames is None:
            # -0 is end even if unknown
            if sec==0:
                return 10**18  # marker for end, caller handles
            return None
        frames=total_frames-pos_sec*rate
    else:
        frames=pos_sec*rate
    return int(round(frames))

def parse_time_samples_plain(s, rate):
    sec=parse_time_terms(s, rate)
    if sec is None: return None
    return int(round(sec*rate))

def format_time_hms(seconds):
    if seconds is None or not math.isfinite(seconds): seconds=0
    if seconds<0: seconds=0
    # round to centiseconds with carry
    cs=int(math.floor(seconds*100+0.5))
    h=cs//360000; m=(cs%360000)//6000; sec=(cs%6000)//100; c=cs%100
    return f"{h:02d}:{m:02d}:{sec:02d}.{c:02d}"

def human_size(val):
    try: v=float(val)
    except: v=0
    if v<1000 and v>=0:
        # file sizes are integer counts; bitrates may be float
        if v==int(v): return str(int(v))
        return ("%g"%v)
    units=['k','M','G','T','P','E']
    idx=-1
    while v>=999.5 and idx < len(units)-1:
        v/=1000.0; idx+=1
    if idx<0:
        return str(int(v))
    u=units[idx]
    if v<10: return f"{v:.2f}{u}"
    elif v<100: return f"{v:.1f}{u}"
    else: return f"{v:.0f}{u}"

def db_to_amp(db):
    return 10.0**(db/20.0)

def amp_to_db(a):
    if a<=0: return -float('inf')
    return 20*math.log10(a)

# RNG (glibc-style attempt + fallback is python's in RNG object)
def rand_float():
    return RNG.random()

def clip_samples(data, mod=None, name=None):
    """Clamp list/array of floats to [-1, 1). Count >range. Return count. data is list/array mutable"""
    cnt=0
    maxv=2147483647/2147483648.0
    for i,v in enumerate(data):
        if v>1.0 or (v>=1.0 and False):
            pass
        if v>=1.0:
            # exactly 1.0 is representable as max? In SoX samples == max is not clip; but float 1.0 maps to max
            if v>1.0: cnt+=1
            data[i]=maxv
        elif v < -1.0:
            cnt+=1; data[i]=-1.0
    if cnt and mod:
        log_warn(mod, f"{name or mod} clipped {cnt} samples; decrease volume?")
    return cnt

def quantize_clip_count(data):
    cnt=0
    for v in data:
        if v>1.0 or v<-1.0: cnt+=1
    return cnt

