    # Use 219 bytes zeros with some FF markers at start pattern
    trailer=bytearray(219)
    return bytes(hdr)+payload+bytes(trailer), clips

def build_maud(audio,encoding,bits):
    payload,clips=encode_pcm_bytes(audio.data,encoding,bits,'big')
    # MHDR 32 bytes: guess fields
    mhdr=bytearray(32)
    struct.pack_into('>I',mhdr,0,audio.frames)
    struct.pack_into('>H',mhdr,4,bits)
    struct.pack_into('>H',mhdr,6,bits)
    struct.pack_into('>I',mhdr,8,int(round(audio.rate)))
