# ---------- Output ----------
def get_comments_for_output(audio, opts):
    if opts.get('comment_file'):
        try:
            txt=open(opts['comment_file'],'r',encoding='utf-8',errors='ignore').read()
            base=[txt.rstrip('\r\n')] if txt.strip() else []
            return base + list(opts.get('add_comment') or [])
        except OSError as ex:
            raise Fail(f"can't open comment file `{opts['comment_file']}': {ex.strerror or ex}","sox",1)
    if opts.get('comment') is not None:
        base=[] if opts['comment']=='' else [opts['comment']]
    else:
        base=list(audio.comments) if audio else []
        if not base:
            base=["Processed by SoX"]
    return base + list(opts.get('add_comment') or [])

def choose_encoding_bits(ftype, audio, opts):
    enc_opt=canonical_encoding(opts.get('encoding')) if opts.get('encoding') else None
    bits_opt=opts.get('bits')
    a_enc=canonical_encoding(audio.encoding) if audio and audio.encoding else "signed-integer"
    a_bits=audio.bits if audio else 32
    a_prec=audio.precision if audio else 32
    # fixed formats
    fixed={
      'sox':("signed-integer",32),'dat':("floating-point",64),'cdda':("signed-integer",16),'cdr':("signed-integer",16),
      'htk':("signed-integer",16),'smp':("signed-integer",16),'sln':("signed-integer",16),
      'sndr':("unsigned-integer",8),'sndt':("unsigned-integer",8),'8svx':("signed-integer",8),
      'wve':("a-law",8),'gsrt':("a-law",8),
    }
    if ftype in RAW_DEFAULTS:
        d_enc,d_bits=RAW_DEFAULTS[ftype]
        if d_enc: return (enc_opt or d_enc, bits_opt or d_bits)
    if ftype in fixed and not enc_opt and not bits_opt:
        return fixed[ftype]
    if enc_opt and bits_opt:
        return enc_opt,int(bits_opt)
    if enc_opt and not bits_opt:
        default_bits={'mu-law':8,'a-law':8,'ima-adpcm':4,'ms-adpcm':4,'oki-adpcm':4,'floating-point':32,'signed-integer':16,'unsigned-integer':16}
        return enc_opt, default_bits.get(enc_opt,16)
    if bits_opt and not enc_opt:
        b=int(bits_opt)
        if ftype=='wav':
            return ("unsigned-integer",8) if b==8 else ("signed-integer",b)
        if ftype in ('aiff',):
            return ("signed-integer",b)
        # default preserve encoding family if compatible else signed
        if a_enc in ("signed-integer","unsigned-integer","floating-point"):
            if ftype=='wav' and a_enc=="signed-integer" and b==8: return ("unsigned-integer",8)
            return (a_enc,b)
        return ("signed-integer",b)
    # no explicit
    if ftype=='wav':
        if a_enc=="floating-point": return ("floating-point", a_bits if a_bits in (32,64) else 32)
        if a_enc in ("mu-law","a-law","ima-adpcm","ms-adpcm"): return (a_enc, a_bits)
        if a_enc=="unsigned-integer": return ("unsigned-integer", a_bits)
        if a_enc=="signed-integer":
            if a_bits==8: return ("unsigned-integer",8)
            return ("signed-integer", a_bits if a_bits in (8,16,24,32) else 32)
        return ("signed-integer",32)
    if ftype in ('wavpcm','amb'):
        if a_enc=="floating-point": return ("signed-integer",32 if a_prec>16 else 16)
        if a_enc=="signed-integer": return ("signed-integer", a_bits if a_bits in (8,16,24,32) else 32)
        if a_enc=="unsigned-integer": return ("unsigned-integer", a_bits)
        return ("signed-integer",16)
    if ftype=='aiff':
        if a_enc=="signed-integer" and a_bits in (8,16,24,32): return (a_enc,a_bits)
        return ("signed-integer", 8 if a_prec<=8 else 16 if a_prec<=16 else 24 if a_prec<=24 else 32)
    if ftype=='aifc':
        if a_enc=="floating-point": return ("floating-point", a_bits if a_bits in (32,64) else 32)
        if a_enc=="signed-integer" and a_bits in (8,16,24,32): return (a_enc,a_bits)
        if a_enc in ("mu-law","a-law"): return (a_enc,8)
        return ("signed-integer", 8 if a_prec<=8 else 16 if a_prec<=16 else 24 if a_prec<=24 else 32)
    if ftype=='au':
        if a_enc in ("signed-integer","mu-law","a-law","floating-point"): return (a_enc, a_bits)
        if a_enc=="unsigned-integer": return ("signed-integer", a_bits)
        return ("signed-integer",16)
    if ftype=='voc':
        return ("signed-integer",16) if a_prec>8 else ("unsigned-integer",8)
    if ftype=='avr':
        if a_prec>8: return ("signed-integer",16)
        return ("signed-integer",8)
    if ftype=='sf':
        if a_enc in ("signed-integer","mu-law","a-law","floating-point"): return (a_enc,a_bits)
        return ("signed-integer", 16 if a_prec<=16 else 32)
    if ftype=='sph':
        if a_enc in ("signed-integer","mu-law"): return (a_enc,a_bits)
        return ("signed-integer", 16 if a_prec<=16 else 32)
    if ftype=='maud':
        return ("signed-integer",16) if a_prec>8 else ("unsigned-integer",8)
    if ftype=='prc':
        return ("a-law",8)
    if ftype=='txw':
        return ("signed-integer",12)
    if ftype=='raw':
        return (a_enc, a_bits)
    # generic defaults
    if a_enc in ("signed-integer","unsigned-integer","floating-point","mu-law","a-law"):
        return (a_enc,a_bits)
    return ("signed-integer",16)

def format_default_endian(ftype):
    if ftype in ('wav','wavpcm','amb','raw','sox','sf','cdda','sln','voc','htk','smp'):
        # htk data is big though format default function not used for fixed? keep little here and special-case writers
        return 'little'
    if ftype in ('aiff','aifc','au','8svx','avr','maud','sph'):
        return 'big'
    if ftype in RAW_DEFAULTS:
        return 'little'
    return 'little'

def write_audio(audio, spec, global_opts=None):
    name=spec['name']; opts=spec['opts']
    if name in ('-n','--null'):
        return None
    if name in ('-d','--default-device'):
        raise Fail("Sorry, there is no default audio device configured","sox",1)
    is_stdout = (name=='-')
    is_pipe = (name in ('-p','--sox-pipe'))
    if is_pipe:
        is_stdout=True
        if not opts.get('type'): opts['type']='sox'
    ext=os.path.splitext(name)[1][1:].lower() if not is_stdout else ''
    ftype=normalize_type(opts.get('type')) if opts.get('type') else None
    if not ftype:
        if ext in EXT_TO_TYPE: ftype=EXT_TO_TYPE[ext]
        elif ext in FORMAT_NAMES: ftype=ext
        elif is_stdout:
            raise Fail("no handler for file extension `'","formats",2)
        else:
            raise Fail(f"no handler for file extension `{ext}'","formats",2)
    if ftype not in FORMAT_NAMES and ftype not in ('m3u','pls'):
        raise Fail(f"no handler for given file type `{opts.get('type')}'","formats",2)
    comments=get_comments_for_output(audio, opts)
    encoding,bits=choose_encoding_bits(ftype, audio, opts)
    endian_def=format_default_endian(ftype)
    endian=apply_endian_opt(opts.get('endian'), endian_def) if opts.get('endian') else endian_def
    if opts.get('endian') and str(opts['endian']).lower()=='swap':
        endian='big' if endian_def=='little' else 'little'
    rate=audio.rate; ch=audio.channels
    data_bytes=b''
    clip_count=0
    # special text / native formats built below; for most PCM:
    if ftype=='dat':
        out_lines=[]
        out_lines.append(f"; Sample Rate {'%g'%rate}\r\n")
        out_lines.append(f"; Channels {ch}\r\n")
        for fr in range(audio.frames):
            t=fr/rate if rate else 0
            row=f"{t:16.8g}"
            for c in range(ch):
                v=audio.data[fr*ch+c]
                if c==0: row+=f"{v:17.11g}"
                else: row+=f"{v:16.11g}"
            row+=" \r\n"
            out_lines.append(row)
        data_bytes=''.join(out_lines).encode()
    elif ftype=='sox':
        comment_str=("\n".join(comments)) if comments else ""
        cb=comment_str.encode()
        pad_len=((len(cb)+7)//8*8) if cb else 0
        hdr_size=32+pad_len
        total_samples=len(audio.data)
        hdr=struct.pack('<4sIQdII', b'.SoX', hdr_size-4, total_samples, float(rate), int(ch), len(cb))
