        hdr=hdr[:32].ljust(32,b'\x00')
        data_bytes=hdr+payload
    elif ftype=='maud':
        data_bytes,clip_count=build_maud(audio,encoding,bits)
    elif ftype in ('sndr',):
        payload,clip_count=encode_pcm_bytes(audio.data,"unsigned-integer",8,'little')
        data_bytes=payload
    elif ftype=='sndt':
        payload,clip_count=encode_pcm_bytes(audio.data,"unsigned-integer",8,'little')
        data_bytes=b'\x00'*128+payload
    elif ftype=='txw':
        payload,clip_count=encode_pcm_bytes(audio.data,"signed-integer",16,'little')
