def get_comments_for_output(audio, opts):
    if opts.get('comment_file'):
        try:
            txt=open(opts['comment_file'],'r',encoding='utf-8',errors='ignore').read()
            base=[txt.rstrip('\r\n')] if txt.strip() else []
            return base + list(opts.get('add_comment') or [])
        except OSError as ex:
            raise Fail(f"can't open comment file `{opts['comment_file']}': {ex.strerror or ex}","sox",1)
    if opts.get('comment') is not None:
        base=[] if opts['comment']=='' else [opts['comment']]
    else:
        base=list(audio.comments) if audio else []
        if not base:
            base=["Processed by SoX"]
    return base + list(opts.get('add_comment') or [])

def choose_encoding_bits(ftype, audio, opts):
