      'sndr':("unsigned-integer",8),'sndt':("unsigned-integer",8),'8svx':("signed-integer",8),
      'wve':("a-law",8),'gsrt':("a-law",8),
    }
    if ftype in RAW_DEFAULTS:
        d_enc,d_bits=RAW_DEFAULTS[ftype]
        if d_enc: return (enc_opt or d_enc, bits_opt or d_bits)
    if ftype in fixed and not enc_opt and not bits_opt:
        return fixed[ftype]
    if enc_opt and bits_opt:
        return enc_opt,int(bits_opt)
    if enc_opt and not bits_opt:
        default_bits={'mu-law':8,'a-law':8,'ima-adpcm':4,'ms-adpcm':4,'oki-adpcm':4,'floating-point':32,'signed-integer':16,'unsigned-integer':16}
        return enc_opt, default_bits.get(enc_opt,16)
    if bits_opt and not enc_opt:
        b=int(bits_opt)
        if ftype=='wav':
            return ("unsigned-integer",8) if b==8 else ("signed-integer",b)
        if ftype in ('aiff',):
            return ("signed-integer",b)
        # default preserve encoding family if compatible else signed
        if a_enc in ("signed-integer","unsigned-integer","floating-point"):
            if ftype=='wav' and a_enc=="signed-integer" and b==8: return ("unsigned-integer",8)
            return (a_enc,b)
        return ("signed-integer",b)
    # no explicit
    if ftype=='wav':
        if a_enc=="floating-point": return ("floating-point", a_bits if a_bits in (32,64) else 32)
        if a_enc in ("mu-law","a-law","ima-adpcm","ms-adpcm"): return (a_enc, a_bits)
        if a_enc=="unsigned-integer": return ("unsigned-integer", a_bits)
        if a_enc=="signed-integer":
            if a_bits==8: return ("unsigned-integer",8)
            return ("signed-integer", a_bits if a_bits in (8,16,24,32) else 32)
        return ("signed-integer",32)
    if ftype in ('wavpcm','amb'):
        if a_enc=="floating-point": return ("signed-integer",32 if a_prec>16 else 16)
        if a_enc=="signed-integer": return ("signed-integer", a_bits if a_bits in (8,16,24,32) else 32)
        if a_enc=="unsigned-integer": return ("unsigned-integer", a_bits)
        return ("signed-integer",16)
    if ftype=='aiff':
        if a_enc=="signed-integer" and a_bits in (8,16,24,32): return (a_enc,a_bits)
        return ("signed-integer", 8 if a_prec<=8 else 16 if a_prec<=16 else 24 if a_prec<=24 else 32)
    if ftype=='aifc':
        if a_enc=="floating-point": return ("floating-point", a_bits if a_bits in (32,64) else 32)
        if a_enc=="signed-integer" and a_bits in (8,16,24,32): return (a_enc,a_bits)
        if a_enc in ("mu-law","a-law"): return (a_enc,8)
        return ("signed-integer", 8 if a_prec<=8 else 16 if a_prec<=16 else 24 if a_prec<=24 else 32)
    if ftype=='au':
        if a_enc in ("signed-integer","mu-law","a-law","floating-point"): return (a_enc, a_bits)
        if a_enc=="unsigned-integer": return ("signed-integer", a_bits)
        return ("signed-integer",16)
    if ftype=='voc':
        return ("signed-integer",16) if a_prec>8 else ("unsigned-integer",8)
    if ftype=='avr':
        if a_prec>8: return ("signed-integer",16)
        return ("signed-integer",8)
    if ftype=='sf':
        if a_enc in ("signed-integer","mu-law","a-law","floating-point"): return (a_enc,a_bits)
        return ("signed-integer", 16 if a_prec<=16 else 32)
    if ftype=='sph':
        if a_enc in ("signed-integer","mu-law"): return (a_enc,a_bits)
        return ("signed-integer", 16 if a_prec<=16 else 32)
    if ftype=='maud':
        return ("signed-integer",16) if a_prec>8 else ("unsigned-integer",8)
    if ftype=='prc':
        return ("a-law",8)
    if ftype=='txw':
        return ("signed-integer",12)
    if ftype=='raw':
        return (a_enc, a_bits)
    # generic defaults
    if a_enc in ("signed-integer","unsigned-integer","floating-point","mu-law","a-law"):
        return (a_enc,a_bits)
    return ("signed-integer",16)

def format_default_endian(ftype):
    if ftype in ('wav','wavpcm','amb','raw','sox','sf','cdda','sln','voc','htk','smp'):
        # htk data is big though format default function not used for fixed? keep little here and special-case writers
        return 'little'
    if ftype in ('aiff','aifc','au','8svx','avr','maud','sph'):
        return 'big'
    if ftype in RAW_DEFAULTS:
        return 'little'
    return 'little'

def write_audio(audio, spec, global_opts=None):
    name=spec['name']; opts=spec['opts']
    if name in ('-n','--null'):
        return None
    if name in ('-d','--default-device'):
        raise Fail("Sorry, there is no default audio device configured","sox",1)
    is_stdout = (name=='-')
    is_pipe = (name in ('-p','--sox-pipe'))
    if is_pipe:
        is_stdout=True
        if not opts.get('type'): opts['type']='sox'
    ext=os.path.splitext(name)[1][1:].lower() if not is_stdout else ''
    ftype=normalize_type(opts.get('type')) if opts.get('type') else None
    if not ftype:
        if ext in EXT_TO_TYPE: ftype=EXT_TO_TYPE[ext]
        elif ext in FORMAT_NAMES: ftype=ext
        elif is_stdout:
            raise Fail("no handler for file extension `'","formats",2)
        else:
            raise Fail(f"no handler for file extension `{ext}'","formats",2)
    if ftype not in FORMAT_NAMES and ftype not in ('m3u','pls'):
        raise Fail(f"no handler for given file type `{opts.get('type')}'","formats",2)
    comments=get_comments_for_output(audio, opts)
    encoding,bits=choose_encoding_bits(ftype, audio, opts)
    endian_def=format_default_endian(ftype)
    endian=apply_endian_opt(opts.get('endian'), endian_def) if opts.get('endian') else endian_def
    if opts.get('endian') and str(opts['endian']).lower()=='swap':
        endian='big' if endian_def=='little' else 'little'
    rate=audio.rate; ch=audio.channels
    data_bytes=b''
    clip_count=0
    # special text / native formats built below; for most PCM:
    if ftype=='dat':
        out_lines=[]
        out_lines.append(f"; Sample Rate {'%g'%rate}\r\n")
        out_lines.append(f"; Channels {ch}\r\n")
        for fr in range(audio.frames):
            t=fr/rate if rate else 0
            row=f"{t:16.8g}"
            for c in range(ch):
                v=audio.data[fr*ch+c]
                if c==0: row+=f"{v:17.11g}"
                else: row+=f"{v:16.11g}"
            row+=" \r\n"
            out_lines.append(row)
        data_bytes=''.join(out_lines).encode()
    elif ftype=='sox':
        comment_str=("\n".join(comments)) if comments else ""
        cb=comment_str.encode()
        pad_len=((len(cb)+7)//8*8) if cb else 0
        hdr_size=32+pad_len
        total_samples=len(audio.data)
        hdr=struct.pack('<4sIQdII', b'.SoX', hdr_size-4, total_samples, float(rate), int(ch), len(cb))
        hdr+=cb + b'\x00'*(pad_len-len(cb))
        payload,_clips=encode_pcm_bytes(audio.data,"signed-integer",32,'little'); clip_count=_clips
        data_bytes=hdr+payload
    elif ftype=='wav' or ftype=='wavpcm' or ftype=='amb':
        data_bytes,clip_count=build_wav(audio,encoding,bits,endian,comments,ftype)
    elif ftype in ('aiff','aifc'):
        data_bytes,clip_count=build_aiff(audio,encoding,bits,endian,comments,ftype)
    elif ftype=='au':
        data_bytes,clip_count=build_au(audio,encoding,bits,endian,comments)
    elif ftype=='voc':
        data_bytes,clip_count=build_voc(audio,encoding,bits,endian,comments)
    elif ftype=='8svx':
        payload,clip_count=encode_pcm_bytes(audio.data,"signed-integer",8,'big')
        data_bytes=build_8svx(audio,payload,comments)
    elif ftype=='avr':
        data_bytes,clip_count=build_avr(audio,encoding,bits)
    elif ftype=='htk':
        payload,clip_count=encode_pcm_bytes(audio.data,"signed-integer",16,'big')
        period=int(round(10000000.0/rate)) if rate else 1250
        if VERBOSITY>=2 and period != (10000000.0/rate if rate else 0):
            pass
        hdr=struct.pack('>IIHH', audio.frames, period, 2, 0)
        data_bytes=hdr+payload
    elif ftype=='sf':
        data_bytes,clip_count=build_sf(audio,encoding,bits,comments)
    elif ftype=='sph':
        data_bytes,clip_count=build_sph(audio,encoding,bits,endian,comments)
    elif ftype=='smp':
        data_bytes,clip_count=build_smp(audio,comments)
    elif ftype=='cdda':
        payload,clip_count=encode_pcm_bytes(audio.data,"signed-integer",16,'little')
        # pad to CDDA sector 2352 bytes
        pad=(2352 - (len(payload)%2352))%2352
        data_bytes=payload+b'\x00'*pad
    elif ftype=='gsrt':
        payload,clip_count=encode_pcm_bytes(audio.data,"a-law",8,'little')
        hdr=bytearray(512)
        # observed header fields are mostly zero with ring.bin name; approximate
        hdr[0:4]=struct.pack('>I',256) if False else b'\x00\x00\x01\x04'
        # put filename
        nameb=b'ring.bin'
        hdr[11:11+len(nameb)]=nameb
        data_bytes=bytes(hdr)+payload
    elif ftype=='wve':
        payload,clip_count=encode_pcm_bytes(audio.data,"a-law",8,'little')
        hdr=b'ALawSoundFile**\x00\x0f\x10\x00\x00\x00\x08\x00\x00\x00\x01\x00\x00\x00\x00\x00\x00'
        # ensure 32 bytes
        hdr=hdr[:32].ljust(32,b'\x00')
        data_bytes=hdr+payload
    elif ftype=='maud':
        data_bytes,clip_count=build_maud(audio,encoding,bits)
    elif ftype in ('sndr',):
        payload,clip_count=encode_pcm_bytes(audio.data,"unsigned-integer",8,'little')
        data_bytes=payload
    elif ftype=='sndt':
        payload,clip_count=encode_pcm_bytes(audio.data,"unsigned-integer",8,'little')
        data_bytes=b'\x00'*128+payload
    elif ftype=='txw':
        payload,clip_count=encode_pcm_bytes(audio.data,"signed-integer",16,'little')
        hdr=bytearray(32)
        hdr[0:6]=b'LM8953'
        data_bytes=bytes(hdr)+payload
        # pad to 512 as original appears to
        pad=(512-(len(data_bytes)%512))%512
        data_bytes+=b'\x00'*pad
    elif ftype=='cvsd' or ftype=='cvu':
        data_bytes=cvsd_encode(audio.data)
    elif encoding=="cvsd":
        data_bytes=cvsd_encode(audio.data)
    else:
        # raw / generic PCM
        if encoding=="ima-adpcm":
            # encode per channel mono assumption in codec; if multichannel interleave already passed but codec resets per sample channel using 1 channel - use channels aware
            payload=ima_encode_samples(audio.data, ch)
            clip_count=0
        elif encoding=="oki-adpcm":
            payload=vox_encode(audio.data); clip_count=0
        else:
            payload,clip_count=encode_pcm_bytes(audio.data,encoding,bits,endian)
        payload=transform_reverse(payload, opts.get('reverse_bits'), opts.get('reverse_nibbles'))
        data_bytes=payload
    if clip_count and name not in ('-n',):
        # SoX reports output clipping from sox (file) unless dither already reported
        if not spec.get('_dither_clipped'):
            log_warn("sox", f"`{name}' output clipped {clip_count} samples; decrease volume?")
    # write out
    if is_stdout:
        try:
            sys.stdout.buffer.write(data_bytes); sys.stdout.buffer.flush()
        except BrokenPipeError:
            pass
        return {'type':ftype,'encoding':encoding,'bits':bits,'endian':endian,'comments':comments}
    # no-clobber handling
    if os.path.exists(name) and global_opts and global_opts.get('no_clobber'):
        # Prompt like original: ask on stderr? Approximate: refuse if no tty input
        try:
            sys.stderr.write(f"Overwrite `{name}'? [y/n] "); sys.stderr.flush()
            ans=sys.stdin.readline()
            if not ans or ans.strip().lower() not in ('y','yes'):
                raise Fail("Aborted","sox",1)
        except Fail: raise
        except Exception:
            raise Fail("Aborted","sox",1)
    if os.path.exists(name) and VERBOSITY>=3:
        log_info("sox", f"Overwriting `{name}'")
    parent=os.path.dirname(os.path.abspath(name))
    # open
    try:
        with open(name,'wb') as f: f.write(data_bytes)
    except OSError as ex:
        raise Fail(f"can't open output file `{name}': {ex.strerror or ex}","formats",2)
    return {'type':ftype,'encoding':encoding,'bits':bits,'endian':endian,'comments':comments}

def build_wav(audio,encoding,bits,endian,comments,ftype='wav'):
    rate=int(round(audio.rate)); ch=audio.channels; frames=audio.frames
    # IMA ADPCM wav
    if encoding=="ima-adpcm":
        # mono only; block size 256 bytes -> 505 samples?
        samples_per_block=505
        payload=bytearray(); clips=0
        # encode block by block restarting IMA
        idx=0
        for start in range(0,frames,samples_per_block):
            chunk=audio.data[start*ch:(start+samples_per_block)*ch]
            pred=int(round(chunk[0]*32768)) if chunk else 0
            pred=max(-32768,min(32767,pred))
            hdr=struct.pack('<hBB',pred,0,0)
            encoded=ima_encode_samples(chunk[1:] if len(chunk)>1 else array('d'),1)
            block=hdr+encoded
            block=block.ljust(256,b'\x00')
            payload+=block[:256]
        blockalign=256; byterate=int(rate*blockalign/samples_per_block) if samples_per_block else rate*256
        fmt_payload=struct.pack('<HHIIHHHH',17,ch,rate,byterate,blockalign,4,2,samples_per_block)
        chunks=b''
        chunks+=b'fmt '+struct.pack('<I',len(fmt_payload))+fmt_payload
        chunks+=b'fact'+struct.pack('<I',4)+struct.pack('<I',frames)
        chunks+=b'data'+struct.pack('<I',len(payload))+bytes(payload)
        riff_size=4+len(chunks)
        return b'RIFF'+struct.pack('<I',riff_size)+b'WAVE'+chunks,0
    if encoding=="ms-adpcm":
        # fallback to IMA style is not correct; encode as PCM16 instead approximation (change encoding handled by caller?) We'll encode PCM16 with tag 1 fallback
        encoding="signed-integer"; bits=16
    # encode data
    if ftype in ('wavpcm','amb'):
        # plain PCM
        enc2=encoding
        if enc2 not in ("signed-integer","unsigned-integer"): enc2="signed-integer"; bits=16 if bits not in (8,16,24,32) else bits
        payload,clips=encode_pcm_bytes(audio.data,enc2,bits,'little')
        # wavpcm 8-bit is unsigned
        if bits==8 and enc2=="signed-integer":
            payload,clips=encode_pcm_bytes(audio.data,"unsigned-integer",8,'little'); enc2="unsigned-integer"
        blockalign=ch*(bits//8); byterate=rate*blockalign
        fmt_payload=struct.pack('<HHIIHH',1,ch,rate,byterate,blockalign,bits)
        chunks=b'fmt '+struct.pack('<I',16)+fmt_payload
        chunks+=b'data'+struct.pack('<I',len(payload))+payload+(b'\x00' if len(payload)%2 else b'')
        return b'RIFF'+struct.pack('<I',4+len(chunks))+b'WAVE'+chunks,clips
    # normal wav
    if encoding in ("signed-integer","unsigned-integer"):
        if bits==8:
            payload,clips=encode_pcm_bytes(audio.data,"unsigned-integer",8,'little')
            fmt_payload=struct.pack('<HHIIHH',1,ch,rate,rate*ch*1,ch*1,8)
            chunks=b'fmt '+struct.pack('<I',16)+fmt_payload
            chunks+=b'data'+struct.pack('<I',len(payload))+payload+(b'\x00' if len(payload)%2 else b'')
            return b'RIFF'+struct.pack('<I',4+len(chunks))+b'WAVE'+chunks,clips
        elif bits==16:
            payload,clips=encode_pcm_bytes(audio.data,"signed-integer",16,'little')
            fmt_payload=struct.pack('<HHIIHH',1,ch,rate,rate*ch*2,ch*2,16)
            chunks=b'fmt '+struct.pack('<I',16)+fmt_payload
            chunks+=b'data'+struct.pack('<I',len(payload))+payload+(b'\x00' if len(payload)%2 else b'')
            return b'RIFF'+struct.pack('<I',4+len(chunks))+b'WAVE'+chunks,clips
        else:
            # extensible 24/32
            payload,clips=encode_pcm_bytes(audio.data,"signed-integer",bits,'little')
            bps=bits//8; blockalign=ch*bps; byterate=rate*blockalign
            mask=4 if ch==1 else (1<<ch)-1
            guid=struct.pack('<IHH',1,0,0x10)+bytes([0x80,0x00,0x00,0xaa,0x00,0x38,0x9b,0x71])
            # GUID bytes: first DWORD 1, then 0000,0010,80...
            fmt_payload=struct.pack('<HHIIHH',0xFFFE,ch,rate,byterate,blockalign,bits)+struct.pack('<HHI',22,bits,mask)+guid
            chunks=b'fmt '+struct.pack('<I',len(fmt_payload))+fmt_payload
            chunks+=b'fact'+struct.pack('<I',4)+struct.pack('<I',frames)
            chunks+=b'data'+struct.pack('<I',len(payload))+payload+(b'\x00' if len(payload)%2 else b'')
            return b'RIFF'+struct.pack('<I',4+len(chunks))+b'WAVE'+chunks,clips
    elif encoding=="floating-point":
        payload,clips=encode_pcm_bytes(audio.data,"floating-point",bits,'little')
        bps=bits//8; blockalign=ch*bps
        fmt_payload=struct.pack('<HHIIHHH',3,ch,rate,rate*blockalign,blockalign,bits,0)
        chunks=b'fmt '+struct.pack('<I',len(fmt_payload))+fmt_payload
        chunks+=b'fact'+struct.pack('<I',4)+struct.pack('<I',frames)
        chunks+=b'data'+struct.pack('<I',len(payload))+payload+(b'\x00' if len(payload)%2 else b'')
        return b'RIFF'+struct.pack('<I',4+len(chunks))+b'WAVE'+chunks,clips
    elif encoding in ("mu-law","a-law"):
        tag=7 if encoding=="mu-law" else 6
        payload,clips=encode_pcm_bytes(audio.data,encoding,8,'little')
        fmt_payload=struct.pack('<HHIIHHH',tag,ch,rate,rate*ch,ch,8,0)
        chunks=b'fmt '+struct.pack('<I',len(fmt_payload))+fmt_payload
        chunks+=b'fact'+struct.pack('<I',4)+struct.pack('<I',frames)
        chunks+=b'data'+struct.pack('<I',len(payload))+payload+(b'\x00' if len(payload)%2 else b'')
        return b'RIFF'+struct.pack('<I',4+len(chunks))+b'WAVE'+chunks,clips
    else:
        payload,clips=encode_pcm_bytes(audio.data,"signed-integer",16,'little')
        fmt_payload=struct.pack('<HHIIHH',1,ch,rate,rate*ch*2,ch*2,16)
        chunks=b'fmt '+struct.pack('<I',16)+fmt_payload+b'data'+struct.pack('<I',len(payload))+payload
        return b'RIFF'+struct.pack('<I',4+len(chunks))+b'WAVE'+chunks,clips

def build_aiff(audio,encoding,bits,endian,comments,ftype):
    rate=audio.rate; ch=audio.channels; frames=audio.frames
    # data endian: AIFF big for signed, AIFC float etc
    data_endian='big'
    compression=None; comp_name=b''
    if ftype=='aifc':
        if encoding=="floating-point":
            compression=b'fl32' if bits==32 else b'fl64'; comp_name=b'float'
            data_endian='big'
        elif encoding=="mu-law":
            compression=b'ulaw'; comp_name=b'mu-law'; bits=8
        elif encoding=="a-law":
            compression=b'alaw'; comp_name=b'a-law'; bits=8
        else:
            if endian=='little':
                compression=b'sowt'; comp_name=b'sowt'
                data_endian='little'
            else:
                compression=b'NONE'; comp_name=b'not compressed'
                data_endian='big'
    else:
        if encoding not in ("signed-integer",):
            encoding="signed-integer"
            if bits not in (8,16,24,32): bits=16
        data_endian='big'
    payload,clips=encode_pcm_bytes(audio.data,encoding,bits,data_endian)
    chunks=b''
    if ftype=='aifc':
        chunks+=b'FVER'+struct.pack('>I',4)+struct.pack('>I',0xa2805140)
        # COMM
        name_bytes=comp_name
        comm=struct.pack('>HIH',ch,frames,bits)+float_to_extended(rate)+compression+struct.pack('B',len(name_bytes))+name_bytes
        if len(comm)%2: comm+=b'\x00'
        chunks+=b'COMM'+struct.pack('>I',len(comm))+comm
    else:
        if comments:
            # COMT
            entries=b''
            # Mac epoch 1904 to unix
            ts=int(time.time()+2082844800) & 0xffffffff
            for ctext in comments:
                tb=ctext.encode('utf-8','ignore')
                entries+=struct.pack('>IHH',ts,0,len(tb))+tb
                if len(tb)%2: entries+=b'\x00'
            comt=struct.pack('>H',len(comments))+entries
            chunks+=b'COMT'+struct.pack('>I',len(comt))+comt+(b'\x00' if len(comt)%2 else b'')
        comm=struct.pack('>HIH',ch,frames,bits)+float_to_extended(rate)
        chunks+=b'COMM'+struct.pack('>I',len(comm))+comm
    ssnd_payload=struct.pack('>II',0,0)+payload
    chunks+=b'SSND'+struct.pack('>I',len(ssnd_payload))+ssnd_payload+(b'\x00' if len(ssnd_payload)%2 else b'')
    form_type=b'AIFC' if ftype=='aifc' else b'AIFF'
    return b'FORM'+struct.pack('>I',4+len(chunks))+form_type+chunks, clips

def build_au(audio,encoding,bits,endian,comments):
    enc_map={("mu-law",8):1,("signed-integer",8):2,("signed-integer",16):3,("signed-integer",24):4,("signed-integer",32):5,("floating-point",32):6,("floating-point",64):7,("a-law",8):27}
    if encoding=="unsigned-integer":
        encoding="signed-integer"
    enc_code=enc_map.get((encoding,bits),3)
    if (encoding,bits) not in enc_map:
        # adjust bits
        if encoding=="floating-point": enc_code=6; bits=32
        elif encoding in ("mu-law",): enc_code=1; bits=8
        elif encoding in ("a-law",): enc_code=27; bits=8
        else: bits=16; enc_code=3
    payload,clips=encode_pcm_bytes(audio.data,encoding,bits,'big')
    comment_str=("\n".join(comments)).encode() if comments else b''
    # offset: header 24 + comment + NUL padded to multiple of 4
    ann_len=len(comment_str)+1
    padded_ann=((ann_len+3)//4)*4
    offset=24+padded_ann
    ann=comment_str + b'\x00'*(padded_ann-len(comment_str))
    hdr=struct.pack('>4s5I', b'.snd', offset, len(payload), enc_code, int(round(audio.rate)), audio.channels)
    return hdr+ann+payload, clips

def build_voc(audio,encoding,bits,endian,comments):
    # Use block type 9 as SoX/newer VOC
    if bits>8 or encoding=="signed-integer" and audio.precision>8:
        payload,clips=encode_pcm_bytes(audio.data,"signed-integer",16,'little')
        bits_used=16; fmt_code=4
    else:
        payload,clips=encode_pcm_bytes(audio.data,"unsigned-integer",8,'little')
        bits_used=8; fmt_code=0
    header=b'Creative Voice File\x1a'+struct.pack('<HHH',26,0x010a,0x1129)
    # block9: type, size (12+len? observed 20 for 16 data => size=len+4) We'll use size=12+len for standard, but to mimic SoX observed for reading by our code either works.
    # Choose SoX-observed convention: size field = 20 when data 16 => data+4 . That appears to be (sizeof(rate?)..) Let's use 12+len? Our reader handles both by reading rest.
    block_payload=struct.pack('<I',int(round(audio.rate)))+struct.pack('BBH',bits_used,audio.channels,fmt_code)+b'\x00'*4
    block=b'\x09'+struct.pack('<I',len(block_payload)+len(payload))[:3]+block_payload+payload
    return header+block+b'\x00', clips

def build_8svx(audio,payload,comments):
    ch=audio.channels
    vhdr=struct.pack('>IIIIHBBI', audio.frames,0,0, int(round(audio.rate)),1,0,0x10000)
    # VHDR is 20 bytes: oneShot, repeat, perCycle, rate(u16), octaves, compression, volume
    chan_val=6 if ch>=2 else 2
