def resample_channel(arr, in_rate, out_rate, mod="rate"):
    if in_rate==out_rate or len(arr)==0:
        return array('d',arr)
    ratio=out_rate/in_rate
    out_len=int(round(len(arr)*ratio))
    if out_len<=0: out_len=1 if len(arr) else 0
    # windowed sinc
    fc=min(1.0, ratio)  # cutoff relative to input sample freq (normalized to input Nyquist? sinc argument)
    # Use filter half width in input samples
