        # For edges normalize by wsum if partial window? Interior wsum ~1. Edge use wsum to avoid droop? Sinc resamplers keep wsum normalization at edges.
        if n>half_width and n < out_len-half_width:
            out[n]=acc
        else:
            out[n]=acc/wsum if abs(wsum)>1e-12 else acc
    return out

