def wsola_channel(arr, rate, factor, segment_ms=82, search_ms=14.68, overlap_ms=12):
    """factor>1 faster (shorter). Returns time-scaled channel"""
    if factor==1.0 or len(arr)==0: return array('d',arr)
    seg=max(16, ms_to_samples(segment_ms, rate))
    search=max(1, ms_to_samples(search_ms, rate))
    overlap=max(1, min(seg-1, ms_to_samples(overlap_ms, rate)))
    # WSOLA implementation
    out=array('d')
    # algorithm: synthesis hop = seg - overlap; analysis hop = synthesis hop * factor
    syn_hop=max(1, seg-overlap)
    ana_hop_float=syn_hop*factor
    # start with first segment
    pos=0.0
    out.extend(arr[:seg])
    pos+=ana_hop_float
    # template is last overlap of out
    while int(pos)+seg < len(arr):
        # search around pos for best correlation with template (last overlap samples of out)
        template=out[-overlap:]
        best_pos=int(round(pos)); best_err=None
        lo=max(0,int(round(pos))-search); hi=min(len(arr)-seg, int(round(pos))+search)
        if hi<lo: break
        # coarse search stride for speed if search large
        stride=1
        # Use sum squared diff
        for cand in range(lo, hi+1):
            err=0.0
            # compare template to arr[cand:cand+overlap]
            # manual loop
            for j in range(overlap):
                diff=template[j]-arr[cand+j]
                err+=diff*diff
                if best_err is not None and err>best_err: break
            if best_err is None or err<best_err:
                best_err=err; best_pos=cand
        # overlap-add segment at best_pos
        seg_arr=arr[best_pos:best_pos+seg]
        # crossfade overlap region
        base_len=len(out)-overlap
        for j in range(overlap):
            fade=j/float(overlap) if overlap else 1
            out[base_len+j]=out[base_len+j]*(1-fade)+seg_arr[j]*fade
        out.extend(seg_arr[overlap:])
        pos=best_pos+ana_hop_float
        # prevent infinite
        if len(out)> len(arr)*3+seg*10: break
    # Trim/pad to expected length
    expected=int(round(len(arr)/factor))
    if len(out)>expected:
        out=out[:expected]
    elif len(out)<expected:
        # append remaining from input tail
        remaining=arr[int(pos):] if int(pos)<len(arr) else array('d')
        out.extend(remaining[:expected-len(out)])
        if len(out)<expected:
            out.extend(array('d',[0.0])*(expected-len(out)))
    return out

