    Q=q_or_slope[1] if isinstance(q_or_slope,tuple) else q_or_slope
    if Q<=0: Q=0.707
    alpha=sw/(2*Q)
    if kind=='lowpass':
        b0=(1-cw)/2; b1=1-cw; b2=(1-cw)/2; a0=1+alpha; a1=-2*cw; a2=1-alpha
    elif kind=='highpass':
        b0=(1+cw)/2; b1=-(1+cw); b2=(1+cw)/2; a0=1+alpha; a1=-2*cw; a2=1-alpha
    elif kind=='bandpass':
        b0=alpha; b1=0; b2=-alpha; a0=1+alpha; a1=-2*cw; a2=1-alpha
    elif kind=='bandpass_skirt':
        b0=sw/2; b1=0; b2=-sw/2; a0=1+alpha; a1=-2*cw; a2=1-alpha
    elif kind=='bandreject' or kind=='notch':
