    dt=1.0/rate; rc=1.0/(2*math.pi*freq) if freq>0 else 0
    alpha=rc/(rc+dt) if rc+dt else 0
    out=array('d',[0.0])*len(arr); y=0.0; xprev=0.0
    for i,x in enumerate(arr):
