        return (b0/a0,b1/a0,b2/a0,1.0,a1/a0,a2/a0)
    Q=q_or_slope[1] if isinstance(q_or_slope,tuple) else q_or_slope
    if Q<=0: Q=0.707
    alpha=sw/(2*Q)
