def effect_channels(audio,n):
    if n==audio.channels: return audio
    chans=deinterleave(audio)
    frames=audio.frames
    if n < audio.channels:
        # Group input channels into n output, averaging groups as channels effect does.
        # SoX channels: it uses a mapping where output channels are mixes with scaling 1/?? For stereo->mono average.
        new=[]
        for out_c in range(n):
            # Determine input channels contributing: those that map round robin? Use partition
            # Partition inputs into n groups as evenly as possible
            contributors=[]
            for in_c in range(audio.channels):
                # mapping used by SoX channels effect: out = in * n / in_chans floor?
                mapped=(in_c*n)//audio.channels
                if mapped==out_c: contributors.append(in_c)
            if not contributors: contributors=[out_c % audio.channels]
            arr=array('d',[0.0])*frames
            for i in range(frames):
                s=sum(chans[c][i] for c in contributors)/len(contributors)
                arr[i]=s
            new.append(arr)
        return reinterleave(audio,new)
    else:
        new=[]
        for out_c in range(n):
            new.append(array('d', chans[out_c % audio.channels]))
