def effect_trim(audio,args):
    if not args:
        return audio
    total=audio.frames
    positions=[]
    prev=0
    for idx,tok in enumerate(args):
        # Determine default prefix '+'
        pos=time_to_samples(tok, audio.rate, total_frames=total, prev=prev, default_prefix='+')
        if pos is None:
            raise UsageFail('trim', pre=[f"Error parsing position {idx+1}"])
        if pos>=10**17: pos=total
        positions.append(pos)
        prev=pos
    # Build copy intervals
    intervals=[]
    state_copy=False
    start=None
    # positions alternate discard/copy starting discard
    # state before first pos: discard
    cur=0
    for i,pos in enumerate(positions):
        pos_clamped=max(0,min(total,pos))
        if i%2==0:
            # this pos begins copy
            intervals.append([pos_clamped,None])
        else:
            if intervals and intervals[-1][1] is None:
                intervals[-1][1]=pos_clamped
    if intervals and intervals[-1][1] is None:
        intervals[-1][1]=total
    # If no intervals (should not)
    chans=deinterleave(audio)
    new=[]
    for arr in chans:
        na=array('d')
        for a,b in intervals:
            na.extend(arr[a:b])
        new.append(na)
    return reinterleave(audio,new)

