def effect_delay(audio,args):
    if not args: raise UsageFail('delay')
    chans=deinterleave(audio)
    new=[]
    for c,arr in enumerate(chans):
        spec=args[c] if c < len(args) else args[-1] if False else '0'
        # If fewer args than channels, remaining channels no delay (SoX: unspecified =0)
        if c>=len(args): spec='0'
