            # Find vol letter scanning after channel digits/hyphen
            # Approach regex: ^([0-9]*)(?:-([0-9]*))?([vpi](.*))?$
            m=re.match(r'^(\d*)(?:-(\d*))?(?:([vpi])(.*))?$',part)
