def effect_fade(audio,args):
    a=list(args)
    ftype='l'  # default? Original default is ??? fade default type is 'l'? Help shows [type] optional; man says default is ??? We'll probe; assume 'l'? Actually first arg may be length if numeric.
    if a and len(a[0])==1 and a[0] in 'qhtlp' and not a[0].isdigit():
        # But 't' could be... fade type letters
        if a[0] in 'qhtlp':
            ftype=a[0]; a=a[1:]
    if not a: raise UsageFail('fade')
    fade_in_sec=parse_time_terms(a[0],audio.rate)
    if fade_in_sec is None: raise UsageFail('fade')
    fade_in=int(round(fade_in_sec*audio.rate))
    stop=None; fade_out=0
    if len(a)>=2:
        # stop position default '='
        stop=time_to_samples(a[1],audio.rate,total_frames=audio.frames,prev=None,default_prefix='=')
        if stop is None: raise UsageFail('fade')
        if stop>=10**17: stop=audio.frames
    if len(a)>=3:
        fo_sec=parse_time_terms(a[2],audio.rate)
        if fo_sec is None: raise UsageFail('fade')
        fade_out=int(round(fo_sec*audio.rate))
    if len(a)>3: raise UsageFail('fade')
    total=audio.frames
    if stop is None: stop=total
    stop=max(0,min(total,stop))
    def curve(x, is_in):
        # x progress 0..1 for fade-in; for fade-out x is progress of fade-out 0..1 gain decreasing
        if ftype=='q':
            return math.sin(x*math.pi/2) if is_in else math.cos(x*math.pi/2)
            # wait fade-out gain: at start 1, end 0: cos works
        if ftype=='h':
            # half sine: fade-in: (sin?) Use 0.5*(1-cos(pi*x))? At x=0 0, x=1 1
            return 0.5*(1-math.cos(math.pi*x)) if is_in else 0.5*(1+math.cos(math.pi*x))
        if ftype=='t' or ftype=='l':
            # t is linear? l is logarithmic? In SoX fade types: l = linear, t = ?? Help says type one of q,h,t,l,p. Man table:
            # We assume l linear, t ??? maybe inverted linear? Check later. Use linear for both l and t for now (t maybe linear too)
            return x if is_in else 1-x
        if ftype=='p':
            # parabola: fade-in x*x ? or sqrt?
