        return x if is_in else 1-x
    # Fade shapes for 't' vs 'l' vs 'p' need refinement: Implement distinguishing:
    # Recreate mapping dict with better guesses:
    def gain_at(i):
        g=1.0
        if fade_in>0 and i<fade_in:
            x=i/fade_in if fade_in else 1
            if ftype=='l':
                # logarithmic: gain = log? SoX log fade: (?) 
                g=curve(x,True)  # currently linear
            elif ftype=='t':
                g=x
            elif ftype=='p':
                g=x*x
            else:
                g=curve(x,True)
        if fade_out>0:
            out_start=stop-fade_out
            if i>=out_start and i<stop:
                x=(i-out_start)/fade_out if fade_out else 1
                if ftype=='q': gf=math.cos(x*math.pi/2)
                elif ftype=='h': gf=0.5*(1+math.cos(math.pi*x))
                elif ftype=='p': gf=(1-x)*(1-x)
                else: gf=1-x
                g*=gf
            elif i>=stop:
                g=0.0
        return g
    chans=deinterleave(audio)
    new=[]
    for arr in chans:
        na=array('d',[0.0])*len(arr)
        for i,v in enumerate(arr):
            na[i]=v*gain_at(i)
        new.append(na)
    # If stop < total and fade_out>0, SoX still outputs to stop? Fade effect does not trim; audio after stop is silent (gain 0). Keep length.
    return reinterleave(audio,new)

