def format_rate_str(rate):
    if rate is None: return "0"
    if abs(rate-round(rate))<1e-9: return str(int(round(rate)))
    return ('%g'%rate)

def display_name_for_spec(spec):
    name=spec['name']; opts=spec['opts']
    if name in ('-n','--null'): return "'' (null)"
    if name in ('-p','--sox-pipe'): return "'' (sox)"
    if name=='-':
        t=opts.get('type')
        return f"'-' ({t})" if t else "'-'"
    return f"'{name}'"

def soxi_block(audio, spec_name, verbose_extra=False, level_adjust=None):
    lines=[]
    lines.append("")
    lines.append(f"Input File     : {spec_name}")
    lines.append(f"Channels       : {audio.channels}")
    lines.append(f"Sample Rate    : {format_rate_str(audio.rate)}")
    lines.append(f"Precision      : {audio.precision}-bit")
    frames=getattr(audio,'soxi_frames', audio.frames)
    known=getattr(audio,'length_known',True) and frames is not None
    if known and frames:
        dur=frames/audio.rate if audio.rate else 0
        lines.append(f"Duration       : {format_time_hms(dur)} = {int(frames)} samples ~ {'%g'%(dur*75)} CDDA sectors")
        lines.append(f"File Size      : {human_size(audio.file_size)}")
        br=audio.file_size*8/dur if dur else 0
        lines.append(f"Bit Rate       : {human_size(br)}")
    enc_disp,_=encoding_display(audio.encoding,audio.bits)
    if getattr(audio,'ftype','')=='dat': enc_disp="Floating Point (text) PCM"
    lines.append(f"Sample Encoding: {enc_disp}")
    if verbose_extra and not audio.is_null:
        lines.append(f"Endian Type    : {audio.endian}")
        # reverse flags from spec opts if available
        lines.append(f"Reverse Nibbles: {'yes' if getattr(audio,'reverse_nibbles',False) else 'no'}")
        lines.append(f"Reverse Bits   : {'yes' if getattr(audio,'reverse_bits',False) else 'no'}")
        if level_adjust is not None:
            lines.append(f"Level adjust   : {'%g'%level_adjust} (linear gain)")
    lines.append("")
