def print_extended_version():
    sys.stdout.write(version_line()+"\n")
    if VERBOSITY>=4:
        import platform
        u=os.uname()
        sys.stdout.write(f"time:     Jun 11 2026 22:07:57\n")
        sys.stdout.write(f"uname:    {u.sysname} {u.nodename} {u.release} {u.version} {u.machine}\n")
        sys.stdout.write(f"compiler: gcc 11.4.0\n")
        sys.stdout.write(f"arch:     1288 48 88 L OMP\n")

def do_help_effect(name):
    sys.stdout.write(version_line()+"\n")
    if name=='all':
        sys.stdout.write(HELP_EFFECTS_ALL_BODY)
        return 1
    if name in EFFECT_USAGES:
        sys.stdout.write("\nEffect usage:\n\n"+EFFECT_USAGES[name]+"\n\n\n")
        return 1
    else:
        sys.stdout.write(f"\nCannot find an effect called `{name}'.\n")
        # print EFFECTS lines from HELP_MAIN
        m=re.search(r'EFFECTS: .*?(?:\n  \* Deprecated[^\n]*\n)', HELP_MAIN, re.S)
        if m: sys.stdout.write(m.group(0))
        return 1

def do_help_format(name):
    sys.stdout.write(version_line()+"\n")
    if name=='all':
        sys.stdout.write(HELP_FORMATS_ALL_BODY)
        if not HELP_FORMATS_ALL_BODY.endswith("\n"): sys.stdout.write("\n")
        return 1
    if name in FORMAT_INFOS:
        sys.stdout.write("\n"+FORMAT_INFOS[name]+"\n")
        return 1
    # alias handling: aif -> aiff etc.
    norm=normalize_type(name)
    if norm in FORMAT_INFOS:
        sys.stdout.write("\n"+FORMAT_INFOS[norm]+"\n")
        return 1
    sys.stdout.write(f"Cannot find a format called `{name}'.\n")
    m=re.search(r'AUDIO FILE FORMATS: .*?(?:\nPLAYLIST FORMATS: [^\n]*\nAUDIO DEVICE DRIVERS: [^\n]*\n)', HELP_MAIN, re.S)
    if m: sys.stdout.write(m.group(0))
    else:
        # fallback extract
        sys.stdout.write("AUDIO FILE FORMATS: "+" ".join(FORMAT_NAMES)+"\n")
    return 1

def parse_effect_tokens(tokens):
    """tokens after files: parse into chains list of lists of (name,args)"""
    chains=[[]]
    i=0
    while i<len(tokens):
        tok=tokens[i]
        if tok==':':
            chains.append([]); i+=1; continue
        if tok in ('newfile','restart'):
            chains[-1].append((tok,[])); i+=1; continue
        if tok not in EFFECT_NAMES:
            # Unknown effect in effect position
            raise Fail(f"Cannot find an effect called `{tok}'","sox",1)
        name=tok; i+=1
        args=[]
        while i<len(tokens) and tokens[i] not in EFFECT_NAMES and tokens[i] not in (':','newfile','restart'):
            args.append(tokens[i]); i+=1
        chains[-1].append((name,args))
    return chains

