    global_opts={'combine':'concatenate' if mode!='play' else 'sequence','no_clobber':False,'guard':False,'norm_global':False,'buffer':None,'effects_file':None,'plot':None,'temp':None}
    if mode=='play': global_opts['combine']='sequence'
