                # special filenames
                if tok in ('-n','--null','-p','--sox-pipe','-d','--default-device','-'):
                    # glob not
                    spec={'name':tok,'opts':dict(pending)}
                    files.append(spec); pending=spec_default_opts(); i+=1; continue
                if tok=='--':
                    end_of_options=True; i+=1; continue
                # effect start?
                if tok in EFFECT_NAMES or tok in (':','newfile','restart'):
                    state='effects'; effects_tokens.append(tok); i+=1; continue
                # options
                if tok.startswith('--') and len(tok)>2:
                    body=tok[2:]
                    if '=' in body:
                        lname,lval=body.split('=',1); has_inline=True
                    else:
                        lname=body; lval=None; has_inline=False
                    # candidates
                    all_long={}
                    for k in GLOBAL_LONG_FLAGS: all_long[k]=('global_flag',GLOBAL_LONG_FLAGS[k][0])
                    for k in GLOBAL_LONG_ARGS: all_long[k]=('global_arg',GLOBAL_LONG_ARGS[k][0])
                    for k in FORMAT_LONG_ARGS: all_long[k]=('format_arg',FORMAT_LONG_ARGS[k][0])
                    for k in FORMAT_LONG_FLAGS: all_long[k]=('format_flag',FORMAT_LONG_FLAGS[k][0])
