                    matched=match_long(lname, list(all_long.keys()))
                    if matched is None:
                        if VERBOSITY>=2: eprint(f"{PROG} WARN getopt: parameter not recognized from `--{lname}'")
                        log_fail("sox","invalid option"); print_help_main(); return 1
                    kind,key=all_long[matched]
