                    val=lval
                    if kind in ('global_arg','format_arg'):
                        if not has_inline:
                            if i+1>=len(argv):
                                if VERBOSITY>=2: eprint(f"{PROG} WARN getopt: `{'--'+matched}' requires an argument from `--{matched}'") if False else eprint(f"{PROG} WARN getopt: parameter `{'--'+matched}' requires an argument")  # placeholder
                                # Original message format for long missing arg: need mimic closest: it said "WARN getopt: `help-effect' requires an argument from `--help-effect'"
                                # We'll redo: clear last print? Can't. This branch rarely happens.
                                log_fail("sox","invalid option"); print_help_main(); return 1
                            val=argv[i+1]; i+=1
                    # handle
                    if kind=='global_flag':
                        if key=='help':
                            print_help_main(); return 0
                        elif key=='version':
                            print_extended_version(); return 0
                        elif key=='clobber': global_opts['no_clobber']=False
                        elif key=='no_clobber': global_opts['no_clobber']=True
                        elif key=='no_dither': NO_DITHER=True
                        elif key=='guard': global_opts['guard']=True
                        elif key=='norm_global': global_opts['norm_global']=True; global_opts['guard']=True
                        elif key=='no_show': SHOW_PROGRESS=False
                        elif key=='show': SHOW_PROGRESS=True
                        elif key=='multi' or key=='single': pass
                    elif kind=='global_arg':
                        if key=='help_effect':
                            return do_help_effect(val)
                        elif key=='help_format':
                            return do_help_format(val)
