def determine_output_info(combined_audio, out_spec):
    name=out_spec['name']; opts=out_spec['opts']
    if name in ('-n','--null'):
        return {'type':'null','encoding':'signed-integer','bits':32,'endian':'little','target_rate':combined_audio.rate,'target_ch':combined_audio.channels,'precision':32,'ftype':'null','comments':[]}
    is_stdout=name=='-' or name in ('-p','--sox-pipe')
    ext=os.path.splitext(name)[1][1:].lower() if not is_stdout else ''
    ftype=normalize_type(opts.get('type')) if opts.get('type') else None
    if name in ('-p','--sox-pipe') and not ftype: ftype='sox'
    if not ftype:
        if ext in EXT_TO_TYPE: ftype=EXT_TO_TYPE[ext]
        elif ext in FORMAT_NAMES: ftype=ext
        else: return None
    if ftype not in FORMAT_NAMES:
        return None
    encoding,bits=choose_encoding_bits(ftype, combined_audio, opts)
    _,precision=encoding_display(encoding,bits)
    if ftype=='dat': precision=54
    endian_def=format_default_endian(ftype)
    endian=apply_endian_opt(opts.get('endian'), endian_def) if opts.get('endian') else endian_def
    if opts.get('endian') and str(opts['endian']).lower()=='swap': endian='big' if endian_def=='little' else 'little'
    target_rate=opts.get('rate') or combined_audio.rate
    target_ch=opts.get('channels') or combined_audio.channels
    # restrictions
    warnings=[]
    restricted_rate=None; restricted_ch=None
    rate_restrictions={'cdda':[44100],'sln':[8000],'gsrt':[8000],'wve':[8000],'prc':[8000],'lpc10':[8000],'txw':[16666.6666667,33333.3333333,50000],'hcom':[22050,11025,7350,5512.5]}
    if ftype in rate_restrictions:
        allowed=rate_restrictions[ftype]
        if float(target_rate) not in [float(x) for x in allowed]:
            # nearest (txw/hcom pick nearest; fixed pick the only)
            chosen=min(allowed, key=lambda x: abs(x-float(target_rate)))
            warnings.append(('formats', f"{ftype} can't encode at {format_rate_str(target_rate)}Hz; using {format_rate_str(chosen)}Hz"))
            restricted_rate=float(chosen); target_rate=float(chosen)
    mono_formats={'htk','smp','sndr','sndt','txw','wve','gsrt','prc','sln','lpc10','vox','ima','cvsd','cvu','dvms'}
    # Note vox/ima as file types are raw mono formats in help
    def ch_desc(n):
        return {1:'mono',2:'stereo',4:'quad'}.get(n, f"{n} channels")
    if ftype=='cdda' and target_ch!=2:
        warnings.append(('formats', f"cdda can't encode {ch_desc(target_ch)}; setting channels to 2")); target_ch=2; restricted_ch=2
    elif ftype in mono_formats and target_ch!=1:
        warnings.append(('formats', f"{ftype} can't encode {ch_desc(target_ch)}; setting channels to 1")); target_ch=1; restricted_ch=1
    elif ftype in ('voc','avr','maud') and target_ch>2:
        warnings.append(('formats', f"{ftype} can't encode {ch_desc(target_ch)}; setting channels to 2")); target_ch=2; restricted_ch=2
    elif ftype=='8svx' and target_ch not in (1,2,4):
        warnings.append(('formats', f"8svx can't encode {ch_desc(target_ch)}; setting channels to 2")); target_ch=2; restricted_ch=2
    return {'type':ftype,'encoding':encoding,'bits':bits,'endian':endian,'target_rate':float(target_rate),'target_ch':int(target_ch),'precision':precision,'ftype':ftype,'warnings':warnings,'restricted_rate':restricted_rate,'restricted_ch':restricted_ch}

def combine_inputs(audios, specs, combine):
    if not audios: return None
    first=audios[0]
    if len(audios)==1 or combine in ('concatenate','sequence'):
        # concatenate
        data=array('d'); prec=first.precision; enc=first.encoding; bits=first.bits
