        out=Audio(first.rate, first.channels, data, prec, enc, bits, first.ftype, list(first.comments), first.file_size, first.name, first.endian)
        out.encoding_name=getattr(first,'encoding_name','')
        out.length_known=all(getattr(a,'length_known',True) for a in audios)
