        max_ch=max(a.channels for a in audios); max_frames=max(a.frames for a in audios)
        manual_any=any(s['opts'].get('volume') is not None for s in specs)
        if combine=='mix': auto_factor=1.0 if manual_any else 1.0/len(audios)
        elif combine=='mix-power': auto_factor=1.0 if manual_any else 1.0/math.sqrt(len(audios))
        else: auto_factor=1.0
