        for a in audios:
            factor=auto_factor
            for fr in range(a.frames):
                for c in range(a.channels):
                    v=a.data[fr*a.channels+c]*factor
                    idx=fr*max_ch+c
                    if combine=='multiply':
                        # multiply handling below needs product init; we will handle separately
                        pass
                    else:
                        data[idx]+=v
        if combine=='multiply':
            # initialise to 1 for channels present?
            data=array('d',[1.0])*(max_frames*max_ch)
            # For frames/channels beyond an input, SoX treats missing as 0 -> product becomes 0. To implement: first fill with first input padded zero, then multiply rest padded zero
            data=array('d',[0.0])*(max_frames*max_ch)
            for fr in range(max_frames):
                for c in range(max_ch):
                    prod=1.0; present=True
                    for a in audios:
                        if fr<a.frames and c<a.channels: prod*=a.data[fr*a.channels+c]
                        else: prod*=0.0
                    data[fr*max_ch+c]=prod
        out=Audio(first.rate, max_ch, data, max(a.precision for a in audios), first.encoding, first.bits, first.ftype, list(first.comments), first.file_size, first.name, first.endian)
