        if seg and seg[0][0]=='__restart__':
            stream=orig.copy(); seg=seg[1:]
            if not seg: continue
        if not seg:
            continue
        # Check for restart inside
        audio_seg=stream.copy()
        # apply effects
        try:
            for (nm,ag) in seg:
                if nm=='__restart__':
                    stream=orig.copy(); audio_seg=stream.copy(); continue
                audio_seg=apply_effect(audio_seg,nm,ag)
        except UsageFail as ex:
            for pre in ex.pre: log_fail(ex.effect,pre)
            log_fail(ex.mod,ex.msg); return ex.code
        except Fail as ex:
            log_fail(ex.mod,ex.msg); return ex.code
        # determine remainder for next segment based on trim consumption
        consumed=None
        for (nm,ag) in seg:
            if nm=='trim' and ag:
                # last position etc: compute consumed as second position if exists
                # parse positions sequentially
                prev=0; poss=[]
                for tok in ag:
                    pos=time_to_samples(tok, orig.rate, total_frames=stream.frames, prev=prev, default_prefix='+')
                    if pos is not None:
                        poss.append(pos); prev=pos
                if len(poss)>=2: consumed=poss[1]
                elif len(poss)==1: consumed=stream.frames
        # write segment
        seg_out_spec={'name':numbered_name(out_spec['name'],out_index),'opts':dict(out_spec['opts'])}
        seg_out_spec['opts']['add_comment']=list(out_spec['opts'].get('add_comment') or [])
        # Use finalize via a helper: temporarily process auto conversions/dither similar to normal - simplify by calling a mini finalize
        rc=finalize_write(audio_seg, seg_out_spec, global_opts)
        if rc!=0: return rc
        out_index+=1
        if consumed is not None and consumed < stream.frames:
            # slice stream from consumed
            chans=deinterleave(stream)
            stream=reinterleave(stream,[arr[consumed:] for arr in chans])
        else:
            # stream exhausted
            stream=Audio(stream.rate,stream.channels,array('d'),stream.precision,stream.encoding,stream.bits)
        if seg and any(nm=='__restart__' for nm,_ in seg):
            stream=orig.copy()
    return 0

def finalize_write(audio, out_spec, global_opts):
    prov=determine_output_info(audio,out_spec)
    if prov is None:
        name=out_spec['name']; ext=os.path.splitext(name)[1][1:].lower() if name!='-' else ''
        if out_spec['opts'].get('type'): log_fail("formats",f"no handler for given file type `{out_spec['opts'].get('type')}'")
        else: log_fail("formats",f"no handler for file extension `{ext}'")
        return 2
    for mod,msg in prov.get('warnings',[]): log_warn(mod,msg)
    target_rate=prov['target_rate']; target_ch=prov['target_ch']
    if audio.channels!=target_ch: audio=effect_channels(audio,target_ch)
    if abs(audio.rate-target_rate)>1e-9: audio=resample_audio(audio,target_rate,mod="rate")
    if not NO_DITHER and prov['precision'] < audio.precision:
        OUT_PRECISION[0]=prov['precision']
        try: audio=effect_dither(audio,[])
        except Exception: pass
    try:
