def slice_audio_from(audio, start):
    if start>=audio.frames:
        out=Audio(audio.rate,audio.channels,array('d'),audio.precision,audio.encoding,audio.bits,audio.ftype,list(audio.comments),0,audio.name,audio.endian)
        out.length_known=getattr(audio,'length_known',True)
        return out
    chans=deinterleave(audio)
    out=audio.copy()
    return reinterleave(out,[arr[start:] for arr in chans])

def concat_audio_list(audios):
    if not audios: return None
    first=audios[0].copy()
    for other in audios[1:]:
        o=other.copy()
        if o.channels!=first.channels: o=effect_channels(o,first.channels)
        if abs(o.rate-first.rate)>1e-9: o=resample_audio(o,first.rate,mod="rate")
        first.data.extend(o.data)
        if o.precision>first.precision: first.precision=o.precision
    return first

def finalize_and_write(audio, out_spec, global_opts, effect_names, base_rate):
    out_info=determine_output_info(audio, out_spec)
    if out_info is None:
        name=out_spec['name']
        if name in ('-n','--null'):
            return 0
        ext=os.path.splitext(name)[1][1:].lower() if name!='-' else ''
        if out_spec['opts'].get('type'): log_fail("formats", f"no handler for given file type `{out_spec['opts'].get('type')}'")
        else: log_fail("formats", f"no handler for file extension `{ext}'")
        return 2
    for mod,msg in out_info.get('warnings',[]): log_warn(mod,msg)
    if out_spec['name'] in ('-n','--null'):
        return 0
    target_rate=out_info['target_rate']; target_ch=out_info['target_ch']
    if not out_spec['opts'].get('rate') and not out_info.get('restricted_rate'):
        last_rate=None
        # effect_names is list of (name,args)
        for nm_,ag_ in effect_names:
            if nm_=='rate':
                for tok_ in ag_:
                    rv=parse_rate(tok_)
                    if rv: last_rate=rv
        target_rate=float(last_rate) if last_rate is not None else float(base_rate)
    if audio.channels!=target_ch: audio=effect_channels(audio,target_ch)
    if abs(audio.rate-target_rate)>1e-9: audio=resample_audio(audio,target_rate,mod="rate")
    if not NO_DITHER and out_info['encoding'] not in ('floating-point','text') and out_info['precision'] < audio.precision and out_info['precision']<24 and 'dither' not in [n for n,_ in effect_names]:
        OUT_PRECISION[0]=out_info['precision']
        try:
            audio=effect_dither(audio,['-s'] if global_opts.get('guard') else [])
        except Exception: pass
    try:
        write_audio(audio,out_spec,global_opts)
    except Fail as ex:
        log_fail(ex.mod,ex.msg); return ex.code
    return 0

def process_segmented(combined, chains, out_spec, global_opts, pre_frames, pre_length_known, has_newfile):
    prov=determine_output_info(combined,out_spec)
    OUT_PRECISION[0]=prov['precision'] if prov else 16
    orig=combined.copy(); remaining=combined.copy()
    # guard/norm insertion into first/last real chains
    chains=[list(c) for c in chains]
    if global_opts.get('guard') or global_opts.get('norm_global'):
        # find first and last chains with a non-pseudo effect
        real_idx=[i for i,c in enumerate(chains) if any(nm not in ('newfile','restart') for nm,_ in c)]
        if real_idx:
            chains[real_idx[0]]=[('gain',['-h'])]+chains[real_idx[0]]
            chains[real_idx[-1]]=chains[real_idx[-1]]+[('gain',['-n'] if global_opts.get('norm_global') else ['-r'])]
    file_segments=[]; current=[]; file_segments.append(current)
    all_effects=[]
    for chain in chains:
        if not chain: continue
        effects=list(chain)
