        while effects and effects[0][0] in ('newfile','restart'):
            if effects[0][0]=='newfile':
                current=[]; file_segments.append(current)
            else:
                remaining=orig.copy()
            effects=effects[1:]
        if not effects: continue
        # split by any embedded newfile
        sublists=[[]]
        for nm,ag in effects:
            if nm=='newfile': sublists.append([])
            else: sublists[-1].append((nm,ag))
        for si,sub in enumerate(sublists):
            if si>0:
                current=[]; file_segments.append(current)
            if sub and sub[0][0]=='restart':
                remaining=orig.copy(); sub=sub[1:]
            if not sub: continue
            seg_in=remaining.copy(); seg_audio=seg_in
            try:
                for nm,ag in sub:
                    all_effects.append((nm,ag))
                    seg_audio=apply_effect(seg_audio,nm,ag)
                    seg_audio.data=quantize_int32_data(seg_audio.data)
            except UsageFail as ex:
                for pre in ex.pre: log_fail(ex.effect,pre)
                log_fail(ex.mod,ex.msg); return ex.code
            except Fail as ex:
                log_fail(ex.mod,ex.msg); return ex.code
            # consumption of the input stream by this chain
            consumed=remaining.frames
            for nm,ag in sub:
