                            if stop is not None: consumed=max(0,min(remaining.frames,stop))
                    break
            current.append(seg_audio)
            remaining=slice_audio_from(remaining, consumed) if consumed<remaining.frames else slice_audio_from(remaining, remaining.frames)
    # write file segments
    segs=[s for s in file_segments if s]
    multiple=has_newfile and len(segs)>1
    def numbered(name,num):
        if re.search(r'%\d*n',name):
            return re.sub(r'%(\d*)n', lambda m: str(num).zfill(int(m.group(1)) if m.group(1) else 1), name)
        if '%n' in name: return name.replace('%n',str(num))
