import math,cmath
def resp(f,fc=440,BW=200,rate=8000):
    R=1-math.pi*BW/rate
    th=2*math.pi*fc/rate; w=2*math.pi*f/rate; z=cmath.exp(1j*w)
    # H(z) = (1-R)*(1-z^-2)/(1-2R cos th z^-1+R^2 z^-2), evaluate z=e^{jw}: use z^-1
    zi=cmath.exp(-1j*w)
    H=(1-R)*(1-zi*zi)/(1-2*R*math.cos(th)*zi+R*R*zi*zi)
    return abs(H)
for f in [100,200,300,440,600,800,1200,2000]: print(f, round(resp(f),3))
print("orig",[0.437,0.503,0.654,1.0,0.48,0.202,0.077,0.029])
